files.content:
html {
  line-height: 1.5;
  block-size: 100%;
  font-size: 16px;
}

body {
  display: grid;
  grid-template-columns: 30% 1fr 1fr 1fr;
  grid-template-rows: 5rlh 15rlh 5rlh;
  grid-template-areas:
    '. header header header'
    '. main main aside'
    'footer footer footer .';
  min-inline-size: 360px;
  min-block-size: 100%;
  margin: 0;
  font-family: 'Open Sans', sans-serif;
  background-image: linear-gradient(rgb(50 50 50 / 0.2) 1px, transparent 1px);
  background-size: 100% 1rlh;
}

h1,
h2,
p,
figure {
  margin: 0;
}

.header__logo {
  max-inline-size: 160px;
}

.main-content img {
  inline-size: 100%;
  border: 1px solid #000;
}

.header {
  grid-area: header;
}

.footer {
  grid-area: footer;
}

.aside {
  grid-area: aside;
}

main {
  grid-area: main;
}

figure {
  position: absolute;
  top: 0;
  left: 0;
  inline-size: 30%;
  overflow: hidden;
}

header,
main,
aside,
footer {
  border: 1px solid #000;
  padding: 1rlh;
  color: #000;
  background-color: rgb(128 217 148 / 0.5);
}

header {
  border-block-end: none;
}

aside {
  border-inline-start: none;
}

header,
footer {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  border: none;
  background-color: rgb(95 13 238 / 0.5);
}

ul {
  display: flex;
  gap: 2rem;
  margin: 0;
  padding: 0;
  font-size: 1rem;
  list-style: none;
}

.header__list {
  flex-direction: column;
  gap: 0;
}

.header__list a {
  color: #000;
  font-weight: 600;
}

.main-content {
  display: flex;
  gap: 2rem;
}

.small-text {
  font-size: 0.75rem;
}

.slogan-text {
  font-weight: 600;
  font-size: 1.25rem;
}

.title {
  margin: 0 0 1.5rem;
  font-size: 2rem;
  line-height: 1.2;
}

.text {
  margin-block-end: 1rem;
  font-size: 1.5rem;
}

.text:last-child {
  margin-block-end: 0;
}

@media (width <= 768px) {
  html {
    font-size: 12px;
  }

  body {
    grid-template-rows: 8rlh 20rlh 5rlh;
  }

  header {
    flex-direction: column;
  }

  .footer__social {
    flex-direction: column;
    gap: 0;
  }

  .header__logo {
    max-inline-size: 100px;
  }
}
